import '../../../../core/network/api_client.dart';
import '../../../../core/network/api_endpoints.dart';
import '../../../../core/utils/json_helpers.dart';
import '../models/employee_model.dart';

/// Result of adding an employee to the organization.
class CreatedEmployee {
  final EmployeeModel employee;

  /// Password generated by the server, shown to the administrator once.
  /// Null when the administrator typed a password, or when the e-mail already
  /// belonged to a registered user (who keeps their own password).
  final String? temporaryPassword;

  const CreatedEmployee({required this.employee, this.temporaryPassword});
}

class EmployeesRepository {
  final ApiClient apiClient;

  EmployeesRepository({required this.apiClient});

  Map<String, dynamic> _data(dynamic body) {
    final map = JsonHelpers.toMap(body);
    return map['data'] is Map ? JsonHelpers.toMap(map['data']) : map;
  }

  /// Employees of the current organization. [departmentId] is a department id
  /// from [getDepartmentList]; [role] is a role id such as `MANAGER`.
  Future<List<EmployeeModel>> getEmployees({
    String? departmentId,
    String? role,
    String? search,
  }) async {
    final query = <String, dynamic>{};
    if (departmentId != null && departmentId.isNotEmpty) {
      query['departmentId'] = departmentId;
    }
    if (role != null && role.isNotEmpty && role.toLowerCase() != 'all') {
      query['role'] = role.toUpperCase();
    }
    if (search != null && search.trim().isNotEmpty) {
      query['search'] = search.trim();
    }

    final response = await apiClient.get(ApiEndpoints.employees, queryParameters: query);
    return JsonHelpers.toList(response.data).map((e) => EmployeeModel.fromJson(JsonHelpers.toMap(e))).toList();
  }

  Future<EmployeeModel> getEmployeeById(String id) async {
    final response = await apiClient.get(ApiEndpoints.employee(id));
    return EmployeeModel.fromJson(_data(response.data));
  }

  Future<CreatedEmployee> createEmployee(Map<String, dynamic> data) async {
    final response = await apiClient.post(ApiEndpoints.employees, data: data);
    final body = JsonHelpers.toMap(response.data);
    final password = JsonHelpers.toStr(body['temporaryPassword']);
    return CreatedEmployee(
      employee: EmployeeModel.fromJson(_data(body)),
      temporaryPassword: password.isEmpty ? null : password,
    );
  }

  /// Departments of the current organization.
  Future<List<DepartmentModel>> getDepartmentList() async {
    final response = await apiClient.get(ApiEndpoints.departments);
    return JsonHelpers.toList(response.data)
        .map((e) => DepartmentModel.fromJson(JsonHelpers.toMap(e)))
        .where((d) => d.id.isNotEmpty && d.name.isNotEmpty)
        .toList();
  }

  /// Department names of the current organization.
  Future<List<String>> getDepartments() async {
    return (await getDepartmentList()).map((d) => d.name).toList();
  }

  Future<EmployeeModel> updateEmployee(String id, Map<String, dynamic> data) async {
    final response = await apiClient.patch(ApiEndpoints.employee(id), data: data);
    return EmployeeModel.fromJson(_data(response.data));
  }

  Future<EmployeeModel> updateEmployeeRole(String id, String role) async {
    final response = await apiClient.patch('${ApiEndpoints.employee(id)}/role', data: {'role': role});
    return EmployeeModel.fromJson(_data(response.data));
  }

  /// Sets a new random password and returns it; it cannot be read again later.
  Future<String> resetPassword(String id) async {
    final response = await apiClient.post('${ApiEndpoints.employee(id)}/reset-password');
    final password = JsonHelpers.toStr(JsonHelpers.toMap(response.data)['temporaryPassword']);
    if (password.isEmpty) throw Exception('Сервер не вернул временный пароль');
    return password;
  }

  /// Removes the employee from the current organization.
  Future<void> removeEmployee(String id) async {
    await apiClient.delete(ApiEndpoints.employee(id));
  }
}
